func TestUnconfiguredWarehouseFallsBackToDefault(t *testing.T) {
	for _, warehouse := range unconfigured {
		if got := LowStockThreshold(warehouse); got != DefaultLowStockThreshold {
			t.Fatalf("LowStockThreshold(%q) = %d, 期望默认值 %d",
