// warehouseQuantity 是一个低库存仓库及其当前数量。
type warehouseQuantity struct {
	warehouse string
	quantity  int
}

// lowStockSorted 返回所有低库存仓库及其数量，按数量升序、数量相同按仓库名升序。
func lowStockSorted(stock map[string]int) []warehouseQuantity {
	low := make([]warehouseQuantity, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouseQuantity{warehouse: warehouse, quantity: quantity})
		}
	}
	sort.Slice(low, func(i, j int) bool {
		if low[i].quantity != low[j].quantity {
			return low[i].quantity < low[j].quantity
		}
		return low[i].warehouse < low[j].warehouse
	})
	return low
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按数量升序、数量相同按仓库名升序。
func LowStockWarehouses(stock map[string]int) []string {
	low := lowStockSorted(stock)
	warehouses := make([]string, len(low))
	for i, item := range low {
		warehouses[i] = item.warehouse
	}
	return warehouses
}
```

