// readThresholds 读取配置里的仓库阈值。文件不存在、读不出来、内容不是 JSON
// 对象时返回 nil。单个仓库的值不是整数（含 null）时只跳过该仓库，让它回退
// 默认值，不影响同一文件里其它有效的配置。
//
// 每次调用都重读配置：仓库规模很小，而且不做缓存可以让测试改写配置文件后
// 立刻生效，不必担心缓存失效。
func readThresholds() map[string]int {
	path := thresholdsFile
	if path == "" {
		path = thresholdsPath()
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil || raw == nil {
		return nil
	}
	thresholds := make(map[string]int, len(raw))
	for warehouse, value := range raw {
		var threshold *int
		if err := json.Unmarshal(value, &threshold); err != nil || threshold == nil {
			continue
		}
		thresholds[warehouse] = *threshold
	}
	return thresholds
}

